input.command:
$reg = Get-ItemProperty "HKLM:\HARDWARE\DESCRIPTION\System\CentralProcessor\0"
$bytes = $reg.'Update Revision'
Write-Host "Raw bytes: $($bytes -join ', ')"
Write-Host "Byte count: $($bytes.Length)"
if ($bytes.Length -ge 8) { $sig = [BitConverter]::ToUInt32($bytes, 4); Write-Host ("Microcode revision: 0x{0:X}" -f $sig) }
elseif ($bytes.Length -ge 4) { $sig = [BitConverter]::ToUInt32($bytes, 0); Write-Host ("Microcode revision: 0x{0:X}" -f $sig) }
